def list_outputs():
    """
    Returns list of outputs
    """
    max_outputs = 32
    data = array.array('b', itertools.repeat(0, max_outputs * _c.STRLEN_LABEL))
    (ptr, _) = data.buffer_info()

    n = _c.xl_list_output(ptr, 33)

    analogOutputs = []
    for i in range(n):
        addr = ptr + i * _c.STRLEN_LABEL
        s = ctypes.string_at(addr)
        analogOutputs.append(s.decode('utf-8'))
    
    n = _c.xl_list_output(ptr, 34)

    digitalOutputs = []
    for i in range(n):
        addr = ptr + i * _c.STRLEN_LABEL
        s = ctypes.string_at(addr)
        digitalOutputs.append(s.decode('utf-8'))
    
    ret = []
    if(len(analogOutputs) and len(digitalOutputs)):
        ret.append(analogOutputs)
        ret.append(digitalOutputs)
    elif(len(analogOutputs)):
        ret = analogOutputs
    elif(len(digitalOutputs)):
        ret = digitalOutputs
    
    return ret
